// Every function takes a record the caller built and uses one of its
// members by kind. Nothing here is annotated: the functions are compiled for
// the record types they are called with.
export function price(entry) {
  return entry.amount.toFixed(2);
}
export function precise(entry) {
  return entry.amount.toPrecision(3) + " " + entry.amount.toString(16);
}
export function stamp(entry) {
  return entry.at.toISOString() + " " + entry.at.getTime();
}
export function tagged(entry) {
  return String(entry.tags.has("new")) + entry.tags.size;
}
export function stock(entry) {
  return String(entry.counts.get("a")) + "/" + entry.counts.size;
}
export function matches(entry) {
  return String(entry.pattern.test("shelf-12")) + " " + entry.pattern.source;
}
export function serial(entry) {
  return entry.serial.toString();
}
export function flag(entry) {
  return entry.open.toString();
}
export function host(entry) {
  return entry.link.hostname;
}
export function rendered(entry) {
  return entry.label.render();
}
export function depth(entry) {
  return entry.box.size.depth.toFixed(1);
}
export function throughLocals(entry) {
  const amount = entry.amount;
  const at = entry.at;
  return amount.toFixed(1) + "@" + at.getUTCFullYear();
}
export function throughChain(entry) {
  return String(entry.amount?.toFixed(0));
}
export const concise = (entry) => entry.amount.toFixed(3);
export function inCallback(entry) {
  return [1, 2].map((factor) => (entry.amount * factor).toFixed(1)).join(",");
}
export function lastName(entry) {
  return String(entry.names.at(-1)) + entry.names.length;
}
// A concise body that calls itself: the whole body is the unit that compiles.
export const countdown = (step) =>
  step.left <= 0 ? "0" : step.left.toFixed(0) + ">" + countdown({ left: step.left - 1 });
